:root {
  --bg: #060b13;
  --panel: rgba(11, 20, 32, 0.7);
  --panel-border: rgba(128, 208, 255, 0.25);
  --gold: #f9d57c;
  --red: #f86a6a;
  --green: #7cefb1;
  --cyan: #8cd8ff;
  --text: #eaf6ff;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  height: 100%;
  background:
    radial-gradient(circle at top, rgba(20, 42, 65, 0.9), rgba(3, 9, 16, 0.96) 52%),
    linear-gradient(180deg, #080d16, #04070d 72%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
  overflow: hidden;
}

body {
  display: grid;
  place-items: center;
}

#game {
  display: block;
  width: min(96vw, 1280px);
  height: min(72vh, 720px);
  background: #050b12;
  border: 1px solid rgba(133, 192, 233, 0.3);
  border-radius: 16px;
  box-shadow: 0 25px 80px rgba(0, 0, 0, 0.45);
}

.hud {
  position: fixed;
  top: 18px;
  left: 50%;
  transform: translateX(-50%);
  width: min(92vw, 1100px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  background: rgba(6, 15, 21, 0.48);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  backdrop-filter: blur(8px);
  z-index: 2;
  pointer-events: none;
}

.title-wrap {
  display: flex;
  flex-direction: column;
}

.title {
  font-size: clamp(1rem, 2vw, 1.8rem);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--gold);
  text-shadow: 0 0 12px rgba(249, 213, 124, 0.45);
}

.subtitle {
  font-size: 0.74rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(224, 240, 255, 0.7);
}

.stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.stat-box {
  min-width: 100px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(15, 30, 43, 0.75);
  border: 1px solid rgba(141, 211, 255, 0.25);
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.label {
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(170, 214, 245, 0.72);
}

.message {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  background: rgba(8, 19, 28, 0.7);
  border: 1px solid rgba(160, 209, 255, 0.3);
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 0.9rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cyan);
  z-index: 2;
}

@media (max-width: 700px) {
  .hud {
    top: 10px;
    width: 94vw;
    padding: 12px 14px;
  }

  .stats {
    gap: 6px;
  }

  .stat-box {
    min-width: 72px;
    padding: 6px 8px;
  }

  .message {
    bottom: 12px;
    width: min(90vw, 420px);
    text-align: center;
    font-size: 0.72rem;
  }
}

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const healthEl = document.getElementById('health');
const waveEl = document.getElementById('wave');
const scoreEl = document.getElementById('score');
const messageEl = document.getElementById('message');

const keys = {};
const pointer = { x: 0, y: 0, down: false };

const arena = {
  half: 12,
  groundY: 0.52,
};

const player = {
  x: 0,
  z: 0,
  radius: 0.9,
  facing: 0,
  speed: 5.1,
  hp: 6,
  maxHp: 6,
  attackCooldown: 0,
  attackSwing: 0,
  parryTimer: 0,
  parryCooldown: 0,
  invuln: 0,
  score: 0,
  wave: 1,
  combo: 0,
  slashFlash: 0,
};

let enemies = [];
let particles = [];
let message = 'Defend the gate. Space = parry, J = slash.';
let gameOver = false;
let victory = false;
let lastTime = 0;

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function randomRange(min, max) {
  return min + Math.random() * (max - min);
}

function distance(a, b) {
  return Math.hypot(a.x - b.x, a.z - b.z);
}

function normalizeAngle(angle) {
  while (angle > Math.PI) angle -= Math.PI * 2;
  while (angle < -Math.PI) angle += Math.PI * 2;
  return angle;
}

function setMessage(text) {
  message = text;
  messageEl.textContent = text;
}

function resetPlayer() {
  player.x = 0;
  player.z = 0;
  player.facing = 0;
  player.hp = player.maxHp;
  player.attackCooldown = 0;
  player.attackSwing = 0;
  player.parryTimer = 0;
  player.parryCooldown = 0;
  player.invuln = 0;
  player.combo = 0;
  player.slashFlash = 0;
  player.wave = 1;
  player.score = 0;
}

function spawnEnemy() {
  const angle = randomRange(-Math.PI, Math.PI);
  const dist = randomRange(6.5, 10.5);
  const x = player.x + Math.cos(angle) * dist;
  const z = player.z + Math.sin(angle) * dist;

  enemies.push({
    x,
    z,
    radius: 0.9,
    hp: 3,
    maxHp: 3,
    speed: randomRange(1.7, 2.2),
    attackCooldown: randomRange(0.8, 1.8),
    attackWindup: 0,
    attackActive: 0,
    hitFlash: 0,
    swingFlash: 0,
    target: null,
  });
}

function spawnWave(waveNumber) {
  const count = Math.min(2 + waveNumber, 6);
  for (let i = 0; i < count; i += 1) {
    spawnEnemy();
  }
  setMessage(`Wave ${waveNumber}: hold the line.`);
}

function startNewGame() {
  resetPlayer();
  enemies = [];
  particles = [];
  gameOver = false;
  victory = false;
  setMessage('Defend the gate. Space = parry, J = slash.');
  spawnWave(1);
  updateHud();
}

function updateHud() {
  healthEl.textContent = `${Math.max(0, Math.ceil(player.hp))} / ${player.maxHp}`;
  waveEl.textContent = String(player.wave);
  scoreEl.textContent = String(player.score);
}

function addParticles(x, z, color, count) {
  for (let i = 0; i < count; i += 1) {
    particles.push({
      x,
      z,
      vx: randomRange(-1.2, 1.2),
      vz: randomRange(-1.2, 1.2),
      life: randomRange(0.4, 0.9),
      color,
      size: randomRange(2, 6),
    });
  }
}

function tryAttack() {
  if (gameOver || victory) return;
  if (player.attackCooldown > 0) return;

  player.attackCooldown = 0.52;
  player.attackSwing = 0.2;
  player.slashFlash = 0.18;

  let hitSomething = false;
  for (const enemy of enemies) {
    const dx = enemy.x - player.x;
    const dz = enemy.z - player.z;
    const dist = Math.hypot(dx, dz);
    const facingDelta = normalizeAngle(Math.atan2(dx, dz) - player.facing);
    if (dist < 2.3 && Math.abs(facingDelta) < 1.1) {
      enemy.hp -= 1;
      enemy.hitFlash = 0.2;
      hitSomething = true;
      addParticles(enemy.x, enemy.z, '#8cd8ff', 10);
      if (enemy.hp <= 0) {
        player.score += 10;
        addParticles(enemy.x, enemy.z, '#f9d57c', 18);
      }
    }
  }

  if (hitSomething) {
    setMessage('Slash confirmed.');
  } else {
    setMessage('The edge whistles past.');
  }
}

function parry() {
  if (gameOver || victory) return;
  if (player.parryCooldown > 0) return;

  player.parryTimer = 0.38;
  player.parryCooldown = 0.52;
  setMessage('Parry ready.');
}

function resolveRiposte(enemy) {
  enemy.hp -= 2;
  enemy.hitFlash = 0.25;
  enemy.attackWindup = 0;
  enemy.attackActive = 0;
  enemy.attackCooldown = 1.1;
  player.score += 25;
  addParticles(enemy.x, enemy.z, '#7cefb1', 20);
  setMessage('Riposte! Enemy staggered.');
  if (enemy.hp <= 0) {
    addParticles(enemy.x, enemy.z, '#f9d57c', 25);
  }
}

function updatePlayer(dt) {
  const dx = (keys['KeyD'] || keys['ArrowRight'] ? 1 : 0) - (keys['KeyA'] || keys['ArrowLeft'] ? 1 : 0);
  const dz = (keys['KeyS'] || keys['ArrowDown'] ? 1 : 0) - (keys['KeyW'] || keys['ArrowUp'] ? 1 : 0);

  if (dx !== 0 || dz !== 0) {
    const len = Math.hypot(dx, dz) || 1;
    const moveX = (dx / len) * player.speed * dt;
    const moveZ = (dz / len) * player.speed * dt;
    player.x += moveX;
    player.z += moveZ;
    player.x = clamp(player.x, -arena.half, arena.half);
    player.z = clamp(player.z, -arena.half, arena.half);
    player.facing = Math.atan2(moveX, moveZ);
  }

  if (player.attackCooldown > 0) {
    player.attackCooldown -= dt;
  }
  if (player.attackSwing > 0) {
    player.attackSwing -= dt;
  }
  if (player.parryTimer > 0) {
    player.parryTimer -= dt;
  }
  if (player.parryCooldown > 0) {
    player.parryCooldown -= dt;
  }
  if (player.invuln > 0) {
    player.invuln -= dt;
  }
  if (player.slashFlash > 0) {
    player.slashFlash -= dt;
  }

  for (const enemy of enemies) {
    if (enemy.hp <= 0) continue;
    const dist = Math.hypot(enemy.x - player.x, enemy.z - player.z);
    const angle = Math.atan2(player.x - enemy.x, player.z - enemy.z);
    const inRange = dist < 2.6;

    if (enemy.attackWindup > 0) {
      enemy.attackWindup -= dt;
      if (enemy.attackWindup <= 0 && inRange) {
        enemy.attackActive = 0.28;
      }
    }

    if (enemy.attackActive > 0) {
      enemy.attackActive -= dt;
      if (enemy.attackActive <= 0) {
        if (inRange) {
          if (player.parryTimer > 0) {
            resolveRiposte(enemy);
          } else {
            player.hp -= 1;
            player.invuln = 0.7;
            addParticles(player.x, player.z, '#f86a6a', 16);
            setMessage('A blade lands. Parry or dodge.');
          }
        }
      }
    }

    if (enemy.attackCooldown > 0) {
      enemy.attackCooldown -= dt;
    }

    if (enemy.hitFlash > 0) {
      enemy.hitFlash -= dt;
    }

    if (enemy.hp > 0 && enemy.attackWindup <= 0 && enemy.attackCooldown <= 0 && dist > 1.4) {
      const chaseX = (player.x - enemy.x) / Math.max(0.2, dist);
      const chaseZ = (player.z - enemy.z) / Math.max(0.2, dist);
      enemy.x += chaseX * enemy.speed * dt;
      enemy.z += chaseZ * enemy.speed * dt;
      enemy.x = clamp(enemy.x, -arena.half, arena.half);
      enemy.z = clamp(enemy.z, -arena.half, arena.half);
    }

    if (dist < 3.1 && enemy.attackCooldown <= 0 && enemy.attackWindup <= 0 && enemy.attackActive <= 0) {
      enemy.attackWindup = 0.72;
      enemy.attackCooldown = 1.4;
    }

    if (enemy.hp <= 0) {
      player.score += 10;
      enemy.attackWindup = 0;
      enemy.attackActive = 0;
      enemy.attackCooldown = 999;
    }
  }

  enemies = enemies.filter((enemy) => enemy.hp > 0);

  if (player.hp <= 0) {
    gameOver = true;
    setMessage('The gate has fallen. Press R to restart.');
  }

  if (enemies.length === 0 && !gameOver && !victory) {
    player.wave += 1;
    if (player.wave > 5) {
      victory = true;
      setMessage('Victory! The gate stands. Press R to replay.');
    } else {
      spawnWave(player.wave);
    }
  }

  updateHud();
}

function projectToScreen(x, z, elevation = 0) {
  const dx = x - player.x;
  const dz = z - player.z;
  const localX = dx * Math.cos(player.facing) - dz * Math.sin(player.facing);
  const localZ = dx * Math.sin(player.facing) + dz * Math.cos(player.facing);

  if (localZ <= -2.5) {
    return null;
  }

  const scale = 540 / (localZ + 8.5);
  const screenX = canvas.width * 0.5 + localX * scale * 28;
  const screenY = canvas.height * (0.77 - elevation * 0.18) - localZ * 14;

  return { x: screenX, y: screenY, scale };
}

function drawArena() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#08131d');
  sky.addColorStop(0.55, '#0c1f2d');
  sky.addColorStop(1, '#040910');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const baseY = canvas.height * 0.7;

  ctx.fillStyle = '#0b1b27';
  ctx.fillRect(0, baseY, canvas.width, canvas.height - baseY);

  for (let i = -8; i <= 8; i += 1) {
    const leftA = projectToScreen(-arena.half, i);
    const leftB = projectToScreen(-arena.half, i + 1);
    const rightA = projectToScreen(arena.half, i);
    const rightB = projectToScreen(arena.half, i + 1);
    if (leftA && rightA && leftB && rightB) {
      ctx.beginPath();
      ctx.moveTo(leftA.x, leftA.y);
      ctx.lineTo(rightA.x, rightA.y);
      ctx.lineTo(rightB.x, rightB.y);
      ctx.lineTo(leftB.x, leftB.y);
      ctx.closePath();
      ctx.fillStyle = i % 2 === 0 ? 'rgba(18, 37, 48, 0.75)' : 'rgba(24, 44, 58, 0.75)';
      ctx.fill();
    }
  }

  for (let i = -8; i <= 8; i += 1) {
    const a = projectToScreen(i, -arena.half);
    const b = projectToScreen(i + 1, -arena.half);
    const c = projectToScreen(i, arena.half);
    const d = projectToScreen(i + 1, arena.half);
    if (a && b && c && d) {
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.lineTo(d.x, d.y);
      ctx.lineTo(c.x, c.y);
      ctx.closePath();
      ctx.strokeStyle = 'rgba(108, 168, 196, 0.25)';
      ctx.stroke();
    }
  }

  const center = projectToScreen(0, 0);
  if (center) {
    ctx.beginPath();
    ctx.arc(center.x, center.y + 8, 16, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(249, 213, 124, 0.12)';
    ctx.fill();
  }
}

function drawEntity(entity, color, isPlayer = false) {
  const proj = projectToScreen(entity.x, entity.z, isPlayer ? 0.1 : 0.45);
  if (!proj) return;

  const radius = isPlayer ? 18 : 14;
  const shadowY = proj.y + 20;
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath();
  ctx.ellipse(proj.x, shadowY, radius * 0.8, radius * 0.45, 0, 0, Math.PI * 2);
  ctx.fill();

  const bodyX = proj.x;
  const bodyY = proj.y;

  if (isPlayer) {
    ctx.fillStyle = player.invuln > 0 ? '#d5f7ff' : '#8fd7ff';
  } else {
    ctx.fillStyle = entity.hitFlash > 0 ? '#ffdb85' : color;
  }

  ctx.beginPath();
  ctx.arc(bodyX, bodyY, radius, 0, Math.PI * 2);
  ctx.fill();

  const angle = Math.atan2(entity.x - player.x, entity.z - player.z);
  const dirX = bodyX + Math.sin(angle) * 18;
  const dirY = bodyY - Math.cos(angle) * 18;
  ctx.strokeStyle = isPlayer ? '#eaf6ff' : '#ffd2d2';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(bodyX, bodyY);
  ctx.lineTo(dirX, dirY);
  ctx.stroke();

  if (isPlayer && player.attackSwing > 0) {
    const slashArc = 1.0 - player.attackSwing / 0.2;
    ctx.strokeStyle = 'rgba(249, 213, 124, 0.9)';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.arc(bodyX, bodyY, 26, -Math.PI * (0.7 - slashArc), Math.PI * (0.25 + slashArc));
    ctx.stroke();
  }

  if (!isPlayer) {
    const hpBarWidth = 30;
    const hpRatio = clamp(entity.hp / entity.maxHp, 0, 1);
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.fillRect(bodyX - hpBarWidth / 2, bodyY - 24, hpBarWidth, 6);
    ctx.fillStyle = '#7cefb1';
    ctx.fillRect(bodyX - hpBarWidth / 2, bodyY - 24, hpBarWidth * hpRatio, 6);
  }
}

function drawParticles() {
  for (const p of particles) {
    const proj = projectToScreen(p.x, p.z, 0.7);
    if (!proj) continue;
    ctx.fillStyle = p.color + 'cc';
    ctx.beginPath();
    ctx.arc(proj.x, proj.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawPlayerState() {
  const center = projectToScreen(player.x, player.z, 0.05);
  if (!center) return;
  ctx.fillStyle = 'rgba(142, 225, 255, 0.15)';
  ctx.fillRect(canvas.width * 0.2, canvas.height * 0.85, canvas.width * 0.6, 18);
  ctx.fillStyle = '#7cefb1';
  const healthRatio = clamp(player.hp / player.maxHp, 0, 1);
  ctx.fillRect(canvas.width * 0.2, canvas.height * 0.85, (canvas.width * 0.6) * healthRatio, 18);
}

function drawGame() {
  drawArena();

  const drawables = [...enemies.map((enemy) => ({ entity: enemy, size: 0, color: '#ff6b6b' })), { entity: player, size: 0, color: '#8fd7ff' }];
  drawables.sort((a, b) => {
    const ap = projectToScreen(a.entity.x, a.entity.z, a.entity === player ? 0.1 : 0.45);
    const bp = projectToScreen(b.entity.x, b.entity.z, b.entity === player ? 0.1 : 0.45);
    if (!ap || !bp) return 0;
    return (bp.x + bp.y) - (ap.x + ap.y);
  });

  const sorted = drawables.map((entry) => entry.entity);
  for (const enemy of sorted) {
    if (enemy === player) continue;
    drawEntity(enemy, '#ff6b6b', false);
  }

  drawEntity(player, '#8fd7ff', true);
  drawParticles();
  drawPlayerState();

  if (gameOver || victory) {
    ctx.fillStyle = 'rgba(6, 10, 18, 0.45)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

function loop(ts) {
  const dt = Math.min(0.033, (ts - lastTime) / 1000 || 0.016);
  lastTime = ts;

  if (!gameOver && !victory) {
    updatePlayer(dt);
  }

  for (const p of particles) {
    p.x += p.vx * dt;
    p.z += p.vz * dt;
    p.life -= dt;
  }
  particles = particles.filter((p) => p.life > 0);

  drawGame();
  requestAnimationFrame(loop);
}

window.addEventListener('keydown', (event) => {
  keys[event.code] = true;
  if (event.code === 'Space') {
    event.preventDefault();
    parry();
  }
  if (event.code === 'KeyJ' || event.code === 'KeyK') {
    tryAttack();
  }
  if (event.code === 'KeyR' && (gameOver || victory)) {
    startNewGame();
  }
});

window.addEventListener('keyup', (event) => {
  keys[event.code] = false;
});

window.addEventListener('pointerdown', (event) => {
  pointer.down = true;
  if (!gameOver && !victory) {
    tryAttack();
  }
});

window.addEventListener('pointermove', (event) => {
  const rect = canvas.getBoundingClientRect();
  pointer.x = (event.clientX - rect.left) / rect.width;
  pointer.y = (event.clientY - rect.top) / rect.height;
  const dx = pointer.x - 0.5;
  const dy = pointer.y - 0.5;
  const angle = Math.atan2(dx, dy);
  if (Math.abs(dx) > 0.02 || Math.abs(dy) > 0.02) {
    player.facing = angle;
  }
});

window.addEventListener('pointerup', () => {
  pointer.down = false;
});

window.addEventListener('resize', () => {
  const width = Math.min(window.innerWidth * 0.96, 1280);
  const height = Math.min(window.innerHeight * 0.8, 720);
  canvas.width = width;
  canvas.height = height;
});

window.dispatchEvent(new Event('resize'));
startNewGame();
requestAnimationFrame(loop);

