.message {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  background: rgba(8, 19, 28, 0.7);
  border: 1px solid rgba(160, 209, 255, 0.3);
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 0.9rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cyan);
  z-index: 2;
}

.touch-controls {
  display: none;
}

.touch-controls button {
  min-width: 46px;
  min-height: 46px;
  border: 1px solid rgba(141, 211, 255, 0.42);
  border-radius: 14px;
  background: rgba(8, 20, 32, 0.82);
  color: var(--text);
  font: inherit;
  font-weight: 700;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

@media (pointer: coarse) {
  .touch-controls {
    position: fixed;
    left: max(16px, env(safe-area-inset-left));
    right: max(16px, env(safe-area-inset-right));
    bottom: max(16px, env(safe-area-inset-bottom));
    display: flex;
    justify-content: space-between;
    align-items: end;
    z-index: 3;
    pointer-events: none;
  }

  .touch-controls button {
    pointer-events: auto;
  }

  .dpad {
    display: grid;
    grid-template-columns: repeat(3, 46px);
    grid-template-rows: repeat(2, 46px);
    gap: 5px;
  }

  .dpad [data-key="KeyW"] { grid-column: 2; grid-row: 1; }
  .dpad [data-key="KeyA"] { grid-column: 1; grid-row: 2; }
  .dpad [data-key="KeyS"] { grid-column: 2; grid-row: 2; }
  .dpad [data-key="KeyD"] { grid-column: 3; grid-row: 2; }

  .action-buttons {
    display: flex;
    gap: 9px;
  }

  .action-buttons button {
    min-width: 64px;
    color: var(--green);
  }

  .action-buttons [data-action="slash"] {
    color: var(--gold);
  }

  .message {
    bottom: max(130px, calc(env(safe-area-inset-bottom) + 115px));
  }
}

